const dialog=document.querySelector('#project-dialog'),content=document.querySelector('.dialog-body');let lastTrigger;
function el(tag,text,cls){const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;}
const groupNamesFallback={'biscuits':'Biscuits & Cookies','cookie-bite':'Cookie Bite','cookie-ball':'Cookie Ball','drink-powder':'Soft Drink Powder','tasty-saline':'Tasty Saline','tiffin':'Tiffin+','ener':'Ener-G'};
function showProduct(index,products){const p=products[index];content.replaceChildren();content.append(el('p',(p.company||'Grameen Danone').toUpperCase()+' / PRODUCT LAUNCH','eyebrow'),el('h2',p.name));content.lastChild.id='dialog-title';content.append(el('p',p.pack,'role'));const stage=el('div',null,'product-detail-stage'),img=el('img');img.src=p.image;img.alt=p.name+' '+p.pack;stage.append(img);content.append(stage);const controls=el('div',null,'product-controls'),prev=el('button','← Previous'),next=el('button','Next →');prev.disabled=index===0;next.disabled=index===products.length-1;prev.onclick=()=>showProduct(index-1,products);next.onclick=()=>showProduct(index+1,products);controls.append(prev,el('span',(index+1)+' / '+products.length),next);content.append(controls);if(!dialog.open)dialog.showModal();document.body.classList.add('modal-open');dialog.scrollTop=0;}
document.querySelector('.close-dialog')?.addEventListener('click',()=>dialog.close());dialog?.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastTrigger?.focus()});
